import { copyFileSync, mkdirSync, readFileSync } from "node:fs";
import { resolve } from "node:path";
import { defineConfig, type Plugin } from "vite";

// Brand assets are generated by brand/make_brand.py; the site serves copies from gallery/public.
const pub = resolve(__dirname, "gallery/public");
mkdirSync(pub, { recursive: true });
for (const [from, to] of [
  ["brand/logo/lockup-light.svg", "lockup-light.svg"],
  ["brand/logo/lockup-dark.svg", "lockup-dark.svg"],
  ["brand/favicon/favicon.svg", "favicon.svg"],
  ["brand/favicon/favicon-32.png", "favicon-32.png"],
  ["brand/favicon/apple-touch-icon.png", "apple-touch-icon.png"],
  ["brand/banners/social-preview.png", "social-preview.png"],
])
  copyFileSync(resolve(__dirname, from), resolve(pub, to));

// The parts of the page that depend on the catalogue (counts, category chips) are written into the
// HTML at build time, so the first paint already has its final layout (no shift when the script runs).
const catalog = JSON.parse(readFileSync(resolve(__dirname, "library/catalog.gen.json"), "utf8")) as {
  categories: Record<string, { title: string }>;
  sounds: { cat: string }[];
};
const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;");
const prerender = (): Plugin => ({
  name: "plinkfx-prerender",
  transformIndexHtml(html) {
    const n = (cat: string) => catalog.sounds.filter((s) => s.cat == cat).length;
    const chips =
      `<button type="button" data-cat="all" aria-pressed="true">all <b>${catalog.sounds.length}</b></button>` +
      Object.entries(catalog.categories)
        .map(([k, c]) => `<button type="button" data-cat="${k}" aria-pressed="false"><i></i>${esc(c.title.toLowerCase())} <b>${n(k)}</b></button>`)
        .join("");
    return html
      .replaceAll("<!--total-->", String(catalog.sounds.length))
      .replaceAll("<!--cats-->", String(Object.keys(catalog.categories).length))
      .replace("<!--chips-->", chips);
  },
});

export default defineConfig({
  plugins: [prerender()],
  root: "gallery",
  base: "./",
  build: {
    outDir: "../site",
    emptyOutDir: true,
    target: "es2020",
    rollupOptions: { input: { index: resolve(__dirname, "gallery/index.html"), game: resolve(__dirname, "gallery/game.html") } },
  },
});
